Here's how to use the Fetch API to get data from a public REST API and display it in an HTML table:

```javascript
async function fetchAndDisplayTable() {
    const container = document.getElementById('data-container');

    try {
        // Fetch data from a public API
        const response = await fetch('https://jsonplaceholder.typicode.com/users');

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();

        // Create table
        const table = document.createElement('table');
        table.style.borderCollapse = 'collapse';
        table.style.width = '100%';

        // Create header row
        const headers = Object.keys(data[0]).slice(0, 5);
        const thead = document.createElement('thead');
        const headerRow = document.createElement('tr');

        headers.forEach(header => {
            const th = document.createElement('th');
            th.textContent = header;
            th.style.border = '1px solid #ddd';
            th.style.padding = '8px';
            th.style.backgroundColor = '#f2f2f2';
            headerRow.appendChild(th);
        });

        thead.appendChild(headerRow);
        table.appendChild(thead);

        // Create body rows
        const tbody = document.createElement('tbody');
        data.forEach(item => {
            const row = document.createElement('tr');

            headers.forEach(header => {
                const td = document.createElement('td');
                td.textContent = item[header];
                td.style.border = '1px solid #ddd';
                td.style.padding = '8px';
                row.appendChild(td);
            });

            tbody.appendChild(row);
        });

        table.appendChild(tbody);
        container.appendChild(table);

    } catch (error) {
        container.innerHTML = `<p>Error fetching data: ${error.message}</p>`;
    }
}

// Call the function when page loads
fetchAndDisplayTable();
```

```html
<div id="data-container"></div>
```

This example fetches user data from JSONPlaceholder, a free fake REST API. The function handles HTTP errors, parses the JSON response, dynamically creates table headers from the data keys, and populates rows. Style the table with CSS for better appearance.
